export function createMemo(fetchValue) {
  const cache = new Map();

  return {
    get(key) {
      if (cache.has(key)) return cache.get(key);

      const pending = Promise.resolve()
        .then(() => fetchValue(key))
        .then(
          value => value,
          reason => {
            cache.delete(key);
            throw reason;
          }
        );

      cache.set(key, pending);
      return pending;
    },

    has(key) {
      return cache.has(key);
    }
  };
}
